import java.io.*;
import java.util.*;

class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        long[] prefixWeight = new long[n + 1];
        int[] changes = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            prefixWeight[i] = prefixWeight[i - 1] + boxes[i - 1][1];
            changes[i] = changes[i - 1];
            if (i > 1 && boxes[i - 1][0] != boxes[i - 2][0]) {
                changes[i]++;
            }
        }

        int[] dp = new int[n + 1];
        int[] deque = new int[n + 1];
        int head = 0, tail = 0;

        for (int i = 1; i <= n; i++) {
            int j = i - 1;
            int value = dp[j] - changes[j + 1];
            while (tail > head) {
                int last = deque[tail - 1];
                int lastValue = dp[last] - changes[last + 1];
                if (lastValue < value) break;
                tail--;
            }
            deque[tail++] = j;

            int minIndex = i - maxBoxes;
            while (head < tail) {
                int first = deque[head];
                if (first >= minIndex && prefixWeight[i] - prefixWeight[first] <= maxWeight) break;
                head++;
            }

            int best = deque[head];
            dp[i] = 2 + changes[i] + dp[best] - changes[best + 1];
        }
        return dp[n];
    }
}

