        s[len++] = (char)ch;
    }
    s[len] = '\0';
    *out = s;
    return (int)len;
}

static int find_top_level_comma(const char *s, int from, int n) {
    int depth = 0;
    for (int i = from; i < n; ++i) {
        if (s[i] == '[') ++depth;
        else if (s[i] == ']') --depth;
        else if (s[i] == ',' && depth == 0) return i;
    }
    return -1;
}

static int parse_boxes(const char *s, int n, int ***out_boxes) {
    int count = 0, cap = 16;
    int **boxes = (int**)malloc(cap * sizeof(int*));
    int values[2];
    int valueCount = 0;

    for (int i = 0; i < n; ) {
        if (s[i] >= '0' && s[i] <= '9') {
            int value = 0;
            while (i < n && s[i] >= '0' && s[i] <= '9') {
                value = value * 10 + (s[i] - '0');
                ++i;
            }
            values[valueCount++] = value;
            if (valueCount == 2) {
                if (count == cap) {
                    cap *= 2;
                    boxes = (int**)realloc(boxes, cap * sizeof(int*));
                }
                int *row = (int*)malloc(2 * sizeof(int));
                row[0] = values[0];
                row[1] = values[1];
                boxes[count++] = row;
                valueCount = 0;
            }
        } else {
            ++i;
        }
    }
    *out_boxes = boxes;
    return count;
}

int boxDelivering(int **boxes, int boxesSize, int *boxesColSize, int portsCount, int maxBoxes, int maxWeight) {
    (void)boxesColSize;
    (void)portsCount;

    long long *prefixWeight = (long long*)calloc((size_t)boxesSize + 1, sizeof(long long));
    int *changes = (int*)calloc((size_t)boxesSize + 1, sizeof(int));
    int *dp = (int*)calloc((size_t)boxesSize + 1, sizeof(int));
    int *dq = (int*)malloc(((size_t)boxesSize + 1) * sizeof(int));

    int head = 0, tail = 0;
    for (int i = 1; i <= boxesSize; ++i) {
        prefixWeight[i] = prefixWeight[i - 1] + boxes[i - 1][1];
        changes[i] = changes[i - 1];
        if (i > 1 && boxes[i - 1][0] != boxes[i - 2][0]) ++changes[i];

        int j = i - 1;
        int value = dp[j] - changes[j + 1];
        while (tail > head) {
            int last = dq[tail - 1];
            if (dp[last] - changes[last + 1] < value) break;
            --tail;
        }
        dq[tail++] = j;

        int minIndex = i - maxBoxes;
        while (head < tail) {
            int first = dq[head];
            if (first >= minIndex && prefixWeight[i] - prefixWeight[first] <= maxWeight) break;
            ++head;
        }

        int best = dq[head];
        dp[i] = 2 + changes[i] + dp[best] - changes[best + 1];
    }

    int result = dp[boxesSize];
    for (int i = 0; i < boxesSize; ++i) free(boxes[i]);
    free(boxes);
    free(prefixWeight);
    free(changes);
    free(dp);
    free(dq);
    return result;
}

